    @JvmStatic
    fun privacyInformationHtml(context: Context): String {
        fun value(key: String): String = profileText(context, key)
            .replace("&", "&amp;")
            .replace("<", "&lt;")
            .replace(">", "&gt;")

        return """
            <!doctype html>
            <html lang="${getSavedLanguage(context)}">
            <head>
              <meta charset="utf-8">
              <meta name="viewport" content="width=device-width, initial-scale=1">
              <style>
                :root { color-scheme: light dark; font: 16px/1.6 sans-serif; }
                body { margin: 0 auto; max-width: 760px; padding: 16px; }
                h1, h2 { line-height: 1.25; }
                h2 { margin-top: 1.5em; }
                .note { opacity: .75; }
                a { color: #3978d4; }
              </style>
            </head>
            <body>
              <main>
                <h1>${value("privacy_doc_title")}</h1>
                <p class="note">${value("privacy_effective_date")}</p>
                <p class="note">${value("privacy_summary_notice")}</p>
                <h2>${value("privacy_information_heading")}</h2>
                <p>${value("privacy_intro")}</p>
                <p>${value("privacy_report_data")}</p>
                <p>${value("privacy_notifications_payments_data")}</p>
                <h2>${value("privacy_use_heading")}</h2>
                <p>${value("privacy_use_data")}</p>
                <h2>${value("privacy_sharing_heading")}</h2>
                <p>${value("privacy_providers_data").replace("2Factor", "Fast2SMS")}</p>
                <p>${value("privacy_sharing_data")}</p>
                <h2>${value("privacy_retention_heading")}</h2>
                <p>${value("privacy_retention_data")}</p>
                <h2>${value("privacy_deletion_heading")}</h2>
                <p>${value("privacy_delete_data")}</p>
                <h2>${value("privacy_security_heading")}</h2>
                <p>${value("privacy_security_contact")}</p>
                <p><a href="https://fendly-api.onrender.com/static/privacy-policy.html">${value("privacy_full_policy_link")}</a></p>
                <p><a href="https://fendly-api.onrender.com/static/delete-account.html">${value("privacy_deletion_page_link")}</a></p>
              </main>
            </body>
            </html>
        """.trimIndent()
    }

    @JvmStatic
    fun wrapContext(context: Context): Context {
        val safeCode = getSavedLanguage(context)
        val locale = Locale.forLanguageTag(safeCode)
        Locale.setDefault(locale)
        val config = Configuration(context.resources.configuration)
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.N) {
            config.setLocales(LocaleList(locale))
        } else {
            @Suppress("DEPRECATION")
            config.locale = locale
        }
        return context.createConfigurationContext(config)
    }

    @JvmStatic
    fun restoreSavedLanguage(context: Context) {
        val safeCode = getSavedLanguage(context)
        AppCompatDelegate.setApplicationLocales(LocaleListCompat.forLanguageTags(safeCode))
        val locale = Locale.forLanguageTag(safeCode)
        Locale.setDefault(locale)
        val resources = context.resources
        val config = Configuration(resources.configuration)
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.N) {
            config.setLocales(LocaleList(locale))
        } else {
            @Suppress("DEPRECATION")
            config.locale = locale
        }
        @Suppress("DEPRECATION")
        resources.updateConfiguration(config, resources.displayMetrics)
    }
